out={'schema':'marici.voevodsky.CR1-single-D03-full-PC-costalk-lift.v1','action':'CR1PK1a2a1a1_construct_single_D03_full_PC_costalk_lift','outcome':'-+','proved':['unique endpoint-normalized bivariant trace on Q03,partial^PC','integral twist-reversed normal Koszul duality','primitive marked carrier line and associated-grade BC square','Tor0 and eta_3,mix Tor1 are both necessarily retained'],'obstruction':'the gallery and road supports are ringed-incomparable; tau0 is not an iterated Thom costalk, and no ringed q-counit/Alexander-Whitney trace exists','negative_control':'reusing the localized entry-97 target contracts the common-base RHom to zero','new_interfaces':['unique_local_Q03partial_PC_bivariant_trace'],'refinement':['CR1PK1a2a1a1a_construct_tau0_A3_filtered_relative_Thom_costalk','CR1PK1a2a1a1b_construct_ringed_staircase_p_q','CR1PK1a2a1a1c_construct_ordered_relative_dualizing_AW_trace','CR1PK1a2a1a1d_test_full_Tor0_Tor1_counit'],'metric_delta':{'formal_coherence_survivors_percent':0.0,'geometrically_certified_complete_paths_percent':0.0,'new_typed_interfaces':1,'newly_blocked_descendant_branches':1},'checks':checks,'passed':True};p=R/'research/voevodsky/results/CR1_single_D03_full_PC_costalk_lift.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'outcome':'-+','survivors':32,'new_interfaces':1,'next':out['refinement'][0]}))
